import {
  supportsConstructiveMutationInput,
  type ConstructiveSchemaSnapshot
} from '../console-kit/constructive/constructive-graphql';

/**
 * The names a Constructive backend gives one membership scope's API. The
 * scope `app` has `appMemberships`, `AppInvite` and `createAppOwnerGrant`; an
 * entity scope such as `data_room` has `dataRoomMemberships`,
 * `DataRoomInvite` and `createDataRoomOwnerGrant`, and its rows carry the
 * entity's id in `entityId`. One scope name in, every name out, so the same
 * code serves `app`, `org` and any entity type a blueprint adds.
 */
export type ScopeNames = Readonly<{
  /** The scope as `membershipTypes.scope` names it: `app`, `org`, `data_room`. */
  scope: string;
  /** `DataRoom`: the prefix of the scope's GraphQL type names. */
  pascal: string;
  /** `dataRoom`: the prefix of the scope's root fields and input objects. */
  camel: string;
  /** Every scope but `app` belongs to one entity, named by `entityId`. */
  entity: boolean;
  /** The scope in words, for messages: `app` and `application` for the app scope. */
  noun: Readonly<{ short: string; long: string }>;
}>;

const SCOPE_NAME = /^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$/u;

const NOUNS: Readonly<Record<string, ScopeNames['noun']>> = {
  app: { short: 'app', long: 'application' },
  org: { short: 'organization', long: 'organization' }
};

export function scopeNames(scope: string): ScopeNames {
  if (!SCOPE_NAME.test(scope)) throw new Error(`"${scope}" is not a membership scope name.`);
  const words = scope.split('_');
  const pascal = words.map((word) => word[0]!.toUpperCase() + word.slice(1)).join('');
  const phrase = words.join(' ');
  return {
    scope,
    pascal,
    camel: pascal[0]!.toLowerCase() + pascal.slice(1),
    entity: scope !== 'app',
    noun: NOUNS[scope] ?? { short: phrase, long: phrase }
  };
}

/** `DataRoom` + `Invite` → `DataRoomInvite`. */
export const scopeType = (names: ScopeNames, suffix: string) => `${names.pascal}${suffix}`;

/** `dataRoom` + `Invites` → `dataRoomInvites`. */
export const scopeField = (names: ScopeNames, suffix: string) => `${names.camel}${suffix}`;

/** `create` + `DataRoom` + `OwnerGrant` → `createDataRoomOwnerGrant`. */
export const scopeMutation = (names: ScopeNames, verb: string, suffix: string) =>
  `${verb}${names.pascal}${suffix}`;

/**
 * The document of one scope mutation. By default it returns its row's id,
 * `createDataRoomInvite(input: $input) { dataRoomInvite { id } }`; a mutation
 * whose payload is something else names what it reads.
 */
export function scopeMutationDocument(
  names: ScopeNames,
  verb: string,
  suffix: string,
  selection = `${scopeField(names, suffix)} { id }`
): string {
  const mutation = scopeMutation(names, verb, suffix);
  const operation = mutation[0]!.toUpperCase() + mutation.slice(1);
  return `
  mutation ConsoleKit${operation}($input: ${operation}Input!) {
    ${mutation}(input: $input) { ${selection} }
  }
`;
}

/** Whether `<verb><Scope><Suffix>` takes its row with these fields: `createDataRoomInvite` with `email`. */
export function supportsScopeObject(
  schema: ConstructiveSchemaSnapshot | undefined,
  names: ScopeNames,
  verb: string,
  suffix: string,
  fields: readonly string[]
): boolean {
  const object = scopeField(names, suffix);
  return supportsConstructiveMutationInput(
    schema,
    scopeMutation(names, verb, suffix),
    [object],
    { field: object, requiredFields: fields }
  );
}

/** Whether `update<Scope><Suffix>` takes a patch with these fields: `updateDataRoomMembership` with `isApproved`. */
export function supportsScopePatch(
  schema: ConstructiveSchemaSnapshot | undefined,
  names: ScopeNames,
  suffix: string,
  fields: readonly string[]
): boolean {
  const patch = scopeField(names, `${suffix}Patch`);
  return supportsConstructiveMutationInput(
    schema,
    scopeMutation(names, 'update', suffix),
    ['id', patch],
    { field: patch, requiredFields: fields }
  );
}

import type {
  AppAccessProfile,
  AppCapability,
  AppClaimedInvite,
  AppInvite,
  AppMember,
  UsersFeatureData
} from '../feature-packs/users/users-feature-pack';
import {
  executeConstructiveConnectionQuery,
  fieldsForType,
  namedTypeName,
  selectExistingFields,
  type ConstructiveSchemaSnapshot
} from '../console-kit/constructive/constructive-graphql';
import {
  asBoolean,
  asRecord,
  asString,
  capabilityMaskIsSubset,
  hasEffectiveCapability,
  imageUrl
} from '../console-kit/constructive/constructive-values';
import { entityUserTypes, loadMembershipTypes, type MembershipType } from './membership-types';
import { scopeField, scopeType, type ScopeNames } from './scope-names';
import { scopeEntityId, type ScopeRuntime, type ScopeSchemas, type ScopeTarget } from './scope-runtime';

export type LoadedScopeAccess = Readonly<{
  data: UsersFeatureData;
  membershipRows: readonly Record<string, unknown>[];
  actorMembership?: Record<string, unknown>;
  memberIds: ReadonlySet<string>;
  actorIds: ReadonlySet<string>;
  memberByActorId: ReadonlyMap<string, AppMember>;
  profileIds: ReadonlySet<string>;
  mutableProfileIds: ReadonlySet<string>;
  capabilityMasks: ReadonlyMap<string, string>;
  ownedInviteIds: ReadonlySet<string>;
  canManageMembers: boolean;
  canManageCapabilities: boolean;
  canCreateInvites: boolean;
  canAssignInviteProfiles: boolean;
  actorIsAdmin: boolean;
  actorIsOwner: boolean;
  ownerCount: number;
}>;

function relationSelection(
  schema: ConstructiveSchemaSnapshot,
  typeName: string,
  fieldName: string,
  desiredFields: readonly string[]
): string | null {
  const field = fieldsForType(schema, typeName)[fieldName];
  const relatedType = namedTypeName(field?.type);
  if (!field || !relatedType) return null;
  const fields = selectExistingFields(schema, relatedType, desiredFields);
  return fields.length > 0 ? `${fieldName} { ${fields.join(' ')} }` : null;
}

function hasQuery(schema: ConstructiveSchemaSnapshot | undefined, field: string): boolean {
  return Boolean(schema?.queryFields[field]);
}

type ScopeAccessSelections = Readonly<{
  memberships: readonly string[];
  invitations: readonly string[];
  acceptedInvites: readonly string[];
  profiles: readonly string[];
  capabilities: readonly string[];
  defaults: readonly string[];
  users: readonly string[];
  emails: readonly string[];
}>;

function accessSelections(schemas: ScopeSchemas, names: ScopeNames): ScopeAccessSelections {
  const admin = schemas.admin;
  if (!admin) throw new Error('The admin endpoint schema is unavailable.');
  const type = (suffix: string) => scopeType(names, suffix);
  const field = (suffix: string) => scopeField(names, suffix);

  const memberships = selectExistingFields(admin, type('Membership'), [
    'id', 'actorId', 'createdAt', 'isOwner', 'isAdmin', 'isActive', 'isApproved',
    'isVerified', 'isBanned', 'isDisabled', 'capabilities', 'granted', 'profileId'
  ]);
  const membershipProfile = relationSelection(admin, type('Membership'), 'profile', ['id', 'name']);
  if (membershipProfile) memberships.push(membershipProfile);
  if (!memberships.includes('id') || !memberships.includes('actorId')) {
    throw new Error(
      `The ${names.noun.short} membership type does not expose its membership and actor identifiers.`
    );
  }

  const invitationFields = selectExistingFields(admin, type('Invite'), [
    'id', 'channel', 'email', 'phone', 'senderId', 'createdAt', 'expiresAt',
    'inviteValid', 'inviteCount', 'inviteLimit', 'multiple', 'profileId'
  ]);
  const invitationProfile = relationSelection(admin, type('Invite'), 'profile', ['id', 'name']);
  if (invitationProfile) invitationFields.push(invitationProfile);
  const invitations = hasQuery(admin, field('Invites')) && invitationFields.includes('id')
    ? invitationFields
    : [];

  const acceptedInviteFields = selectExistingFields(admin, type('ClaimedInvite'), [
    'id', 'senderId', 'receiverId', 'createdAt'
  ]);
  const acceptedInvites = hasQuery(admin, field('ClaimedInvites')) &&
    acceptedInviteFields.includes('id')
    ? acceptedInviteFields
    : [];

  const profileFields = selectExistingFields(admin, type('Profile'), [
    'id', 'name', 'slug', 'description', 'capabilities', 'isSystem', 'isDefault',
    'createdAt', 'updatedAt'
  ]);
  const profiles = hasQuery(admin, field('Profiles')) &&
    profileFields.includes('id') && profileFields.includes('name')
    ? profileFields
    : [];

  const capabilityFields = selectExistingFields(admin, type('Capability'), [
    'id', 'name', 'description', 'bitnum', 'bitstr'
  ]);
  const capabilities = hasQuery(admin, field('Capabilities')) &&
    capabilityFields.includes('id') && capabilityFields.includes('name') &&
    capabilityFields.includes('bitstr')
    ? capabilityFields
    : [];

  const defaultFields = selectExistingFields(admin, type('CapabilityDefault'), ['id', 'capabilities']);
  const defaults = hasQuery(admin, field('CapabilityDefaults')) &&
    defaultFields.includes('capabilities')
    ? defaultFields
    : [];

  const auth = schemas.auth;
  const userFields = auth
    ? selectExistingFields(auth, 'User', ['id', 'displayName', 'username', 'profilePicture', 'type'])
    : [];
  const users = hasQuery(auth, 'users') && userFields.includes('id') ? userFields : [];
  const emailFields = auth ? selectExistingFields(auth, 'Email', ['ownerId', 'email', 'isPrimary']) : [];
  const emails = hasQuery(auth, 'emails') &&
    emailFields.includes('ownerId') && emailFields.includes('email')
    ? emailFields
    : [];

  return { memberships, invitations, acceptedInvites, profiles, capabilities, defaults, users, emails };
}

function capabilityIdsForMask(
  mask: unknown,
  capabilityRows: readonly Record<string, unknown>[]
): string[] {
  return capabilityRows.flatMap((capability) => {
    const id = asString(capability.id);
    return id && capabilityMaskIsSubset(capability.bitstr, mask) ? [id] : [];
  });
}

function relatedProfile(
  value: unknown,
  profileId: string | null,
  profileById: ReadonlyMap<string, AppAccessProfile>
): Readonly<{ id: string; name: string }> | undefined {
  const related = asRecord(value);
  const relatedId = asString(related?.id);
  const relatedName = asString(related?.name);
  if (relatedId && relatedName) return { id: relatedId, name: relatedName };
  if (profileId && profileById.has(profileId)) {
    return { id: profileId, name: profileById.get(profileId)!.name };
  }
  return undefined;
}

const NO_ACCESS: LoadedScopeAccess = {
  data: { members: [] },
  membershipRows: [],
  memberIds: new Set(),
  actorIds: new Set(),
  memberByActorId: new Map(),
  profileIds: new Set(),
  mutableProfileIds: new Set(),
  capabilityMasks: new Map(),
  ownedInviteIds: new Set(),
  canManageMembers: false,
  canManageCapabilities: false,
  canCreateInvites: false,
  canAssignInviteProfiles: false,
  actorIsAdmin: false,
  actorIsOwner: false,
  ownerCount: 0
};

type Rows = readonly Record<string, unknown>[];

/** One scope's rows as the signed-in actor reads them, before they become the users view. */
type AccessRows = Readonly<{
  membershipRows: Rows;
  invitationRows: Rows;
  acceptedInviteRows: Rows;
  profileRows: Rows;
  capabilityRows: Rows;
  defaultRows: Rows;
  userRows: Rows;
  emailRows: Rows;
  /** The users-table types that mark an entity, not a person. */
  entityTypes: ReadonlySet<number>;
}>;

async function readAccessRows(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  target: ScopeTarget,
  selections: ScopeAccessSelections,
  signal: AbortSignal
): Promise<AccessRows> {
  const { names } = target;
  const entityId = scopeEntityId(target);
  const operation = (suffix: string) => `ConsoleKit${names.pascal}Access${suffix}`;
  const ofEntity = entityId ? { entityId } : undefined;
  const connection = (
    endpoint: 'auth' | 'admin',
    operationName: string,
    fieldName: string,
    nodeFields: readonly string[],
    equalTo?: Readonly<Record<string, string>>
  ): Promise<Record<string, unknown>[]> => nodeFields.length > 0
    ? executeConstructiveConnectionQuery(runtime, endpoint, {
        operationName,
        fieldName,
        nodeSelection: nodeFields.join(' '),
        ...(equalTo ? { equalTo } : {})
      }, signal)
    : Promise.resolve([]);

  const [
    membershipRows,
    invitationRows,
    acceptedInviteRows,
    profileRows,
    capabilityRows,
    defaultRows,
    userRows,
    emailRows,
    membershipTypes
  ] = await Promise.all([
    connection('admin', operation('MembershipsPage'), scopeField(names, 'Memberships'), selections.memberships, ofEntity),
    connection('admin', operation('InvitationsPage'), scopeField(names, 'Invites'), selections.invitations, ofEntity),
    connection('admin', operation('AcceptedInvitesPage'), scopeField(names, 'ClaimedInvites'), selections.acceptedInvites, ofEntity),
    connection('admin', operation('ProfilesPage'), scopeField(names, 'Profiles'), selections.profiles, ofEntity),
    connection('admin', operation('CapabilitiesPage'), scopeField(names, 'Capabilities'), selections.capabilities),
    connection('admin', operation('CapabilityDefaultsPage'), scopeField(names, 'CapabilityDefaults'), selections.defaults, ofEntity),
    connection('auth', operation('UsersPage'), 'users', selections.users),
    // Membership directory access does not imply access to private emails.
    connection('auth', operation('EmailsPage'), 'emails', selections.emails)
      .catch((): Record<string, unknown>[] => []),
    selections.users.includes('type')
      ? loadMembershipTypes(runtime, schemas.admin, signal).catch((): MembershipType[] => [])
      : Promise.resolve([])
  ]);
  return {
    membershipRows,
    invitationRows,
    acceptedInviteRows,
    profileRows,
    capabilityRows,
    defaultRows,
    userRows,
    emailRows,
    // An organization is a row in the users table too, so it can hold a
    // membership; it is an entity, not a person, and stays off the members list.
    entityTypes: entityUserTypes(membershipTypes)
  };
}

// The users view of the rows, and what the actor may change in it.
function scopeAccessOf(rows: AccessRows, selections: ScopeAccessSelections, actorId: string): LoadedScopeAccess {
  const {
    membershipRows,
    invitationRows,
    acceptedInviteRows,
    profileRows,
    capabilityRows,
    defaultRows,
    userRows,
    emailRows,
    entityTypes
  } = rows;
  const users = new Map(userRows.flatMap((user) => {
    const id = asString(user.id);
    return id ? [[id, user] as const] : [];
  }));
  const emails = new Map<string, string>();
  for (const email of emailRows) {
    const ownerId = asString(email.ownerId);
    const value = asString(email.email);
    if (!ownerId || !value) continue;
    if (!emails.has(ownerId) || asBoolean(email.isPrimary)) emails.set(ownerId, value);
  }

  const capabilityMasks = new Map<string, string>();
  const capabilities: AppCapability[] = capabilityRows.flatMap((capability) => {
    const id = asString(capability.id);
    const name = asString(capability.name);
    const bitstr = asString(capability.bitstr);
    if (!id || !name || !bitstr) return [];
    capabilityMasks.set(id, bitstr);
    return [{
      id,
      name,
      description: asString(capability.description) ?? undefined,
      bit: typeof capability.bitnum === 'number' ? capability.bitnum : undefined
    }];
  });

  const profileMemberCounts = new Map<string, number>();
  for (const membership of membershipRows) {
    const profileId = asString(membership.profileId) ?? asString(asRecord(membership.profile)?.id);
    if (profileId) profileMemberCounts.set(profileId, (profileMemberCounts.get(profileId) ?? 0) + 1);
  }
  const profiles: AppAccessProfile[] = profileRows.flatMap((profile) => {
    const id = asString(profile.id);
    const name = asString(profile.name);
    if (!id || !name) return [];
    return [{
      id,
      name,
      slug: asString(profile.slug) ?? undefined,
      description: asString(profile.description) ?? undefined,
      capabilityIds: capabilityIdsForMask(profile.capabilities, capabilityRows),
      system: asBoolean(profile.isSystem),
      default: asBoolean(profile.isDefault),
      memberCount: profileMemberCounts.get(id) ?? 0
    }];
  });
  const profileById = new Map(profiles.map((profile) => [profile.id, profile] as const));

  const members: AppMember[] = membershipRows.flatMap((membership) => {
    const id = asString(membership.id);
    const userId = asString(membership.actorId);
    if (!id || !userId) return [];
    const user = users.get(userId);
    if (typeof user?.type === 'number' && entityTypes.has(user.type)) return [];
    const username = asString(user?.username);
    const email = emails.get(userId) ?? (username?.includes('@') ? username : 'Private email');
    const profileId = asString(membership.profileId) ?? asString(asRecord(membership.profile)?.id);
    return [{
      id,
      userId,
      name: asString(user?.displayName) ?? username ?? email,
      email,
      avatarUrl: imageUrl(user?.profilePicture),
      lifecycle: {
        approved: asBoolean(membership.isApproved),
        // An organization's or an entity's memberships have no verified flag.
        ...(selections.memberships.includes('isVerified') ? { verified: asBoolean(membership.isVerified) } : {}),
        banned: asBoolean(membership.isBanned),
        disabled: asBoolean(membership.isDisabled),
        active: asBoolean(membership.isActive)
      },
      governance: {
        owner: asBoolean(membership.isOwner),
        admin: asBoolean(membership.isAdmin)
      },
      profile: relatedProfile(membership.profile, profileId, profileById),
      directCapabilityIds: capabilityIdsForMask(membership.granted, capabilityRows),
      effectiveCapabilityIds: capabilityIdsForMask(membership.capabilities, capabilityRows),
      joinedAt: asString(membership.createdAt) ?? undefined
    }];
  });
  const memberByActorId = new Map(members.map((member) => [member.userId, member] as const));

  const ownedInviteIds = new Set<string>();
  const invitations: AppInvite[] = invitationRows.flatMap((invite) => {
    const id = asString(invite.id);
    if (!id) return [];
    const recipient = asString(invite.email) ?? asString(invite.phone) ?? 'General invitation';
    const isOwned = asString(invite.senderId) === actorId;
    if (isOwned) ownedInviteIds.add(id);
    const profileId = asString(invite.profileId) ?? asString(asRecord(invite.profile)?.id);
    return [{
      id,
      recipient,
      channel: asString(invite.channel) ?? undefined,
      status: asBoolean(invite.inviteValid) ? 'pending' : 'expired',
      profile: relatedProfile(invite.profile, profileId, profileById),
      createdAt: asString(invite.createdAt) ?? undefined,
      expiresAt: asString(invite.expiresAt) ?? undefined,
      useCount: typeof invite.inviteCount === 'number' ? invite.inviteCount : undefined,
      useLimit: typeof invite.inviteLimit === 'number' ? invite.inviteLimit : undefined,
      actionPolicy: { cancelInvite: isOwned, extendInvite: isOwned }
    }];
  });

  const acceptedInvites: AppClaimedInvite[] = acceptedInviteRows.flatMap((invite) => {
    const id = asString(invite.id);
    if (!id) return [];
    const senderId = asString(invite.senderId) ?? undefined;
    const receiverId = asString(invite.receiverId) ?? undefined;
    return [{
      id,
      senderId,
      senderName: senderId ? memberByActorId.get(senderId)?.name : undefined,
      receiverId,
      receiverName: receiverId ? memberByActorId.get(receiverId)?.name : undefined,
      acceptedAt: asString(invite.createdAt) ?? undefined
    }];
  });

  const actorMembership = membershipRows.find((membership) => asString(membership.actorId) === actorId);
  const hasActiveMembership = asBoolean(actorMembership?.isActive);
  const actorIsOwner = hasActiveMembership && asBoolean(actorMembership?.isOwner);
  const actorIsAdmin = hasActiveMembership && asBoolean(actorMembership?.isAdmin);
  const hasNamedCapability = (capabilityName: string) => hasActiveMembership &&
    hasEffectiveCapability(actorMembership, capabilityRows, capabilityName);
  const canManageMembers = actorIsAdmin || hasNamedCapability('admin_members');
  const canManageCapabilities = actorIsAdmin || hasNamedCapability('admin_capabilities');
  const canCreateInvites = actorIsAdmin || hasNamedCapability('create_invites');
  const canAssignInviteProfiles = actorIsAdmin || hasNamedCapability('assign_profiles');

  const inviteProfileIds = profiles.flatMap((profile) => {
    const source = profileRows.find((row) => asString(row.id) === profile.id);
    const allowed = hasActiveMembership && (
      actorIsAdmin || capabilityMaskIsSubset(source?.capabilities, actorMembership?.capabilities)
    );
    return allowed ? [profile.id] : [];
  });
  const defaultCapabilityIds = selections.defaults.length > 0 && selections.capabilities.length > 0
    ? capabilityIdsForMask(defaultRows[0]?.capabilities, capabilityRows)
    : undefined;

  return {
    data: {
      members,
      ...(selections.invitations.length > 0 ? { invitations } : {}),
      ...(selections.acceptedInvites.length > 0 ? { acceptedInvites } : {}),
      ...(selections.profiles.length > 0 ? { profiles } : {}),
      ...(selections.capabilities.length > 0 ? { capabilities } : {}),
      ...(defaultCapabilityIds ? { defaultCapabilityIds } : {}),
      ...(selections.profiles.length > 0 ? { inviteProfileIds } : {})
    },
    membershipRows,
    actorMembership,
    memberIds: new Set(members.map((member) => member.id)),
    actorIds: new Set(members.map((member) => member.userId)),
    memberByActorId,
    profileIds: new Set(profiles.map((profile) => profile.id)),
    mutableProfileIds: new Set(profiles.filter((profile) => !profile.system).map((profile) => profile.id)),
    capabilityMasks,
    ownedInviteIds,
    canManageMembers,
    canManageCapabilities,
    canCreateInvites,
    canAssignInviteProfiles,
    actorIsAdmin,
    actorIsOwner,
    ownerCount: members.filter((member) => member.governance.owner).length
  };
}

/**
 * Reads one scope's members, invitations, profiles, capabilities and defaults
 * as the signed-in actor, and what that actor may change. An entity scope's
 * rows are limited to its entity; RLS decides the rest.
 */
export async function loadScopeAccess(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  target: ScopeTarget,
  signal: AbortSignal
): Promise<LoadedScopeAccess> {
  if (runtime.session.status !== 'authenticated') return NO_ACCESS;
  const selections = accessSelections(schemas, target.names);
  const rows = await readAccessRows(runtime, schemas, target, selections, signal);
  return scopeAccessOf(rows, selections, runtime.session.identity.subjectId);
}

import type {
  AppAccessProfile,
  AppMember,
  UsersFeatureData,
  UsersFeaturePackProps
} from '../feature-packs/users/users-feature-pack';
import { capitalized } from '../feature-packs/users/users-scope-noun';
import {
  executeConstructiveGraphQL,
  supportsConstructiveMutationInput
} from '../console-kit/constructive/constructive-graphql';
import { assertAuthorizedTarget, expiresIn } from '../console-kit/constructive/constructive-values';
import type { LoadedScopeAccess } from './scope-access-load';
import {
  scopeField,
  scopeMutation,
  scopeMutationDocument,
  supportsScopeObject,
  supportsScopePatch,
  type ScopeNames
} from './scope-names';
import { scopeEntityId, type ScopeRuntime, type ScopeSchemas, type ScopeTarget } from './scope-runtime';

/** What the users view takes besides its data: the resource, the policy and the actions. */
export type ScopeAccessView = Readonly<{
  resource: UsersFeaturePackProps['resource'];
  policy: NonNullable<UsersFeaturePackProps['policy']>;
  actions: NonNullable<UsersFeaturePackProps['actions']>;
}>;

type LifecycleField = 'isApproved' | 'isVerified' | 'isBanned' | 'isDisabled';

function assertMutableMember(
  directory: LoadedScopeAccess,
  names: ScopeNames,
  membershipId: string,
  label: string
): AppMember {
  assertAuthorizedTarget(directory.memberIds, membershipId, `${names.noun.short} membership`);
  const member = directory.data.members.find((candidate) => candidate.id === membershipId);
  if (!member) throw new Error(`The requested ${names.noun.short} membership is unavailable.`);
  if (member.governance.owner) {
    throw new Error(`${capitalized(names.noun.long)} owners cannot be ${label} through membership lifecycle fields.`);
  }
  return member;
}

/** The bits set in any of the masks; the masks of one scope share a length. */
function unionMask(masks: readonly string[]): string {
  return [...masks[0]!].map((_, index) => (masks.some((mask) => mask[index] === '1') ? '1' : '0')).join('');
}

/**
 * The users view of one scope: its rows with each row's allowed actions, the
 * scope-wide policy, and the actions themselves. Every write names the
 * scope's own mutation, and an entity scope's writes carry its `entityId`.
 */
export function scopeAccessView(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  target: ScopeTarget,
  directory: LoadedScopeAccess,
  reload: () => void
): ScopeAccessView {
  const { names } = target;
  const entityId = scopeEntityId(target);
  const ofEntity = entityId ? { entityId } : {};
  const admin = schemas.admin;
  const supportsObject = (verb: string, suffix: string, fields: readonly string[]) =>
    supportsScopeObject(admin, names, verb, suffix, fields);
  const write = async (verb: string, suffix: string, input: Record<string, unknown>) => {
    await executeConstructiveGraphQL(runtime, 'admin', scopeMutationDocument(names, verb, suffix), { input });
    reload();
  };
  const object = (suffix: string, fields: Record<string, unknown>) => ({
    [scopeField(names, suffix)]: { ...fields, ...ofEntity }
  });
  const patch = (suffix: string, id: string, fields: Record<string, unknown>) => ({
    id,
    [scopeField(names, `${suffix}Patch`)]: fields
  });
  const label = names.noun.short;

  const canSetApproved = directory.canManageMembers && supportsScopePatch(admin, names, 'Membership', ['isApproved']);
  const canSetVerified = directory.canManageMembers && supportsScopePatch(admin, names, 'Membership', ['isVerified']);
  const canSetBanned = directory.canManageMembers && supportsScopePatch(admin, names, 'Membership', ['isBanned']);
  const canSetDisabled = directory.canManageMembers && supportsScopePatch(admin, names, 'Membership', ['isDisabled']);
  const canSetOwner = directory.actorIsOwner &&
    supportsObject('create', 'OwnerGrant', ['actorId', 'isGrant']);
  const canSetAdmin = directory.actorIsAdmin &&
    supportsObject('create', 'AdminGrant', ['actorId', 'isGrant']);
  const canSetDirectCapability = directory.canManageMembers && directory.capabilityMasks.size > 0 &&
    supportsObject('create', 'Grant', ['actorId', 'capabilities', 'isGrant']);
  const canSetProfile = directory.canManageMembers && directory.profileIds.size > 0 &&
    supportsObject('create', 'ProfileGrant', ['membershipId', 'profileId', 'isGrant']);
  const canComposeProfiles = directory.canManageCapabilities && directory.profileIds.size > 0 &&
    directory.capabilityMasks.size > 0 &&
    supportsObject('create', 'ProfileDefinitionGrant', ['profileId', 'capabilityId', 'isGrant']);
  const canSetDefaultCapability = directory.canManageCapabilities && directory.capabilityMasks.size > 0 &&
    directory.data.defaultCapabilityIds !== undefined &&
    supportsObject('create', 'CapabilityDefaultGrant', ['capabilityId', 'isGrant']);

  const canCreateProfile = directory.canManageCapabilities &&
    supportsObject('create', 'Profile', ['name', 'slug']);
  const createProfileSupportsDescription = supportsObject('create', 'Profile', ['description']);
  const createProfileSupportsCapabilities = supportsObject('create', 'Profile', ['capabilities']);
  const canUpdateProfile = directory.canManageCapabilities && directory.mutableProfileIds.size > 0 &&
    supportsScopePatch(admin, names, 'Profile', ['name', 'slug']);
  const updateProfileSupportsDescription = supportsScopePatch(admin, names, 'Profile', ['description']);
  const canSetDefaultProfile = directory.canManageCapabilities && directory.mutableProfileIds.size > 0 &&
    supportsScopePatch(admin, names, 'Profile', ['isDefault']);
  const canDeleteProfile = directory.canManageCapabilities && directory.mutableProfileIds.size > 0 &&
    supportsConstructiveMutationInput(admin, scopeMutation(names, 'delete', 'Profile'), ['id']);

  const canCreateInvite = directory.canCreateInvites && supportsObject('create', 'Invite', ['email']);
  const inviteSupportsExpiry = supportsObject('create', 'Invite', ['expiresAt']);
  const inviteSupportsChannel = supportsObject('create', 'Invite', ['channel']);
  const inviteSupportsProfile = supportsObject('create', 'Invite', ['profileId']);
  const canUpdateInvite = directory.ownedInviteIds.size > 0 &&
    supportsScopePatch(admin, names, 'Invite', ['expiresAt']);
  const canDeleteInvite = directory.ownedInviteIds.size > 0 &&
    supportsConstructiveMutationInput(admin, scopeMutation(names, 'delete', 'Invite'), ['id']);

  const members = directory.data.members.map((member): AppMember => ({
    ...member,
    actionPolicy: {
      setApproved: canSetApproved && !member.governance.owner,
      setVerified: canSetVerified && !member.governance.owner,
      setBanned: canSetBanned && !member.governance.owner,
      setDisabled: canSetDisabled && !member.governance.owner,
      setOwner: canSetOwner && (!member.governance.owner || directory.ownerCount > 1),
      setAdmin: canSetAdmin && !member.governance.owner,
      setProfile: canSetProfile,
      setDirectCapability: canSetDirectCapability
    }
  }));
  const profiles = directory.data.profiles?.map((profile): AppAccessProfile => ({
    ...profile,
    actionPolicy: {
      updateProfile: canUpdateProfile && !profile.system,
      deleteProfile: canDeleteProfile && !profile.system,
      setDefaultProfile: canSetDefaultProfile && !profile.system,
      setProfileCapability: canComposeProfiles && !profile.system
    }
  }));
  const data: UsersFeatureData = { ...directory.data, members, ...(profiles ? { profiles } : {}) };
  const hasVisibleRows = data.members.length > 0 || Boolean(data.invitations?.length) ||
    Boolean(data.acceptedInvites?.length) || Boolean(data.profiles?.length) ||
    Boolean(data.capabilities?.length);
  const knownCapabilityIds = new Set(directory.capabilityMasks.keys());

  const setLifecycle = (field: LifecycleField, verb: string) =>
    async (membershipId: string, value: boolean) => {
      assertMutableMember(directory, names, membershipId, verb);
      await write('update', 'Membership', patch('Membership', membershipId, { [field]: value }));
    };

  return {
    resource: hasVisibleRows ? { status: 'ready', data, quality: 'authoritative' } : { status: 'empty' },
    policy: {
      invite: canCreateInvite,
      assignInviteProfile: canCreateInvite && directory.canAssignInviteProfiles &&
        Boolean(data.inviteProfileIds?.length) && inviteSupportsProfile,
      setApproved: canSetApproved,
      setVerified: canSetVerified,
      setBanned: canSetBanned,
      setDisabled: canSetDisabled,
      setOwner: canSetOwner,
      setAdmin: canSetAdmin,
      setProfile: canSetProfile,
      setDirectCapability: canSetDirectCapability,
      createProfile: canCreateProfile,
      updateProfile: canUpdateProfile,
      deleteProfile: canDeleteProfile,
      setDefaultProfile: canSetDefaultProfile,
      setProfileCapability: canComposeProfiles,
      setDefaultCapability: canSetDefaultCapability,
      cancelInvite: canDeleteInvite,
      extendInvite: canUpdateInvite
    },
    actions: {
      invite: canCreateInvite
        ? async ({ recipient, profileId }) => {
            if (profileId) {
              assertAuthorizedTarget(
                new Set(data.inviteProfileIds ?? []), profileId, `${label} invitation profile`
              );
              if (!directory.canAssignInviteProfiles || !inviteSupportsProfile) {
                throw new Error('An access profile cannot be assigned to this invitation.');
              }
            }
            await write('create', 'Invite', object('Invite', {
              email: recipient,
              ...(inviteSupportsChannel ? { channel: 'email' } : {}),
              ...(inviteSupportsExpiry ? { expiresAt: expiresIn(7) } : {}),
              ...(profileId ? { profileId } : {})
            }));
          }
        : undefined,
      setApproved: canSetApproved
        ? ({ membershipId, approved }) =>
            setLifecycle('isApproved', 'approved or unapproved')(membershipId, approved)
        : undefined,
      setVerified: canSetVerified
        ? ({ membershipId, verified }) =>
            setLifecycle('isVerified', 'verified or unverified')(membershipId, verified)
        : undefined,
      setBanned: canSetBanned
        ? ({ membershipId, banned }) =>
            setLifecycle('isBanned', 'banned or unbanned')(membershipId, banned)
        : undefined,
      setDisabled: canSetDisabled
        ? ({ membershipId, disabled }) =>
            setLifecycle('isDisabled', 'disabled or enabled')(membershipId, disabled)
        : undefined,
      setOwner: canSetOwner
        ? async ({ userId, owner }) => {
            assertAuthorizedTarget(directory.actorIds, userId, `${label} member`);
            const member = directory.memberByActorId.get(userId);
            if (!member) throw new Error(`The requested ${label} member is unavailable.`);
            if (!owner && member.governance.owner && directory.ownerCount <= 1) {
              throw new Error(`The final ${names.noun.long} owner cannot be revoked.`);
            }
            await write('create', 'OwnerGrant', object('OwnerGrant', { actorId: userId, isGrant: owner }));
          }
        : undefined,
      setAdmin: canSetAdmin
        ? async ({ userId, admin: grant }) => {
            assertAuthorizedTarget(directory.actorIds, userId, `${label} member`);
            const member = directory.memberByActorId.get(userId);
            if (member?.governance.owner && !grant) {
              throw new Error(
                `${capitalized(names.noun.long)} owners retain admin access until ownership is revoked.`
              );
            }
            await write('create', 'AdminGrant', object('AdminGrant', { actorId: userId, isGrant: grant }));
          }
        : undefined,
      setDirectCapability: canSetDirectCapability
        ? async ({ userId, capabilityId, granted }) => {
            assertAuthorizedTarget(directory.actorIds, userId, `${label} member`);
            assertAuthorizedTarget(knownCapabilityIds, capabilityId, `${label} capability`);
            await write('create', 'Grant', object('Grant', {
              actorId: userId,
              capabilities: directory.capabilityMasks.get(capabilityId),
              isGrant: granted
            }));
          }
        : undefined,
      setProfile: canSetProfile
        ? async ({ membershipId, profileId }) => {
            assertAuthorizedTarget(directory.memberIds, membershipId, `${label} membership`);
            if (profileId) assertAuthorizedTarget(directory.profileIds, profileId, `${label} access profile`);
            await write('create', 'ProfileGrant', object('ProfileGrant', {
              membershipId,
              ...(profileId ? { profileId } : {}),
              isGrant: Boolean(profileId)
            }));
          }
        : undefined,
      createProfile: canCreateProfile
        ? async ({ name, slug, description, capabilityIds }) => {
            const masks = (capabilityIds ?? []).map((capabilityId) => {
              assertAuthorizedTarget(knownCapabilityIds, capabilityId, `${label} capability`);
              return directory.capabilityMasks.get(capabilityId)!;
            });
            if (masks.length > 0 && !createProfileSupportsCapabilities) {
              throw new Error('This profile cannot be created with capabilities.');
            }
            await write('create', 'Profile', object('Profile', {
              name,
              slug,
              ...(createProfileSupportsDescription && description ? { description } : {}),
              ...(masks.length > 0 ? { capabilities: unionMask(masks) } : {})
            }));
          }
        : undefined,
      updateProfile: canUpdateProfile
        ? async ({ profileId, name, slug, description }) => {
            assertAuthorizedTarget(directory.mutableProfileIds, profileId, `mutable ${label} access profile`);
            await write('update', 'Profile', patch('Profile', profileId, {
              name,
              slug,
              ...(updateProfileSupportsDescription ? { description: description ?? null } : {})
            }));
          }
        : undefined,
      deleteProfile: canDeleteProfile
        ? async ({ profileId }) => {
            assertAuthorizedTarget(directory.mutableProfileIds, profileId, `mutable ${label} access profile`);
            await write('delete', 'Profile', { id: profileId });
          }
        : undefined,
      setDefaultProfile: canSetDefaultProfile
        ? async ({ profileId }) => {
            assertAuthorizedTarget(directory.mutableProfileIds, profileId, `mutable ${label} access profile`);
            await write('update', 'Profile', patch('Profile', profileId, { isDefault: true }));
          }
        : undefined,
      setProfileCapability: canComposeProfiles
        ? async ({ profileId, capabilityId, granted }) => {
            assertAuthorizedTarget(directory.mutableProfileIds, profileId, `mutable ${label} access profile`);
            assertAuthorizedTarget(knownCapabilityIds, capabilityId, `${label} capability`);
            // A definition grant names the profile, which already belongs to the entity.
            await executeConstructiveGraphQL(
              runtime,
              'admin',
              scopeMutationDocument(names, 'create', 'ProfileDefinitionGrant'),
              { input: { [scopeField(names, 'ProfileDefinitionGrant')]: { profileId, capabilityId, isGrant: granted } } }
            );
            reload();
          }
        : undefined,
      setDefaultCapability: canSetDefaultCapability
        ? async ({ capabilityId, granted }) => {
            assertAuthorizedTarget(knownCapabilityIds, capabilityId, `${label} capability`);
            await write('create', 'CapabilityDefaultGrant', object('CapabilityDefaultGrant', {
              capabilityId,
              isGrant: granted
            }));
          }
        : undefined,
      cancelInvite: canDeleteInvite
        ? async ({ inviteId }) => {
            assertAuthorizedTarget(directory.ownedInviteIds, inviteId, `${label} invitation`);
            await write('delete', 'Invite', { id: inviteId });
          }
        : undefined,
      extendInvite: canUpdateInvite
        ? async ({ inviteId }) => {
            assertAuthorizedTarget(directory.ownedInviteIds, inviteId, `${label} invitation`);
            await write('update', 'Invite', patch('Invite', inviteId, { expiresAt: expiresIn(7) }));
          }
        : undefined
    }
  };
}

import {
  createFetchConsoleTransport,
  createIdentityScopedTransport,
  type ConsoleEndpoint,
  type ConsoleEndpointKind,
  type ConsoleIdentity,
  type ConsoleSessionSnapshot
} from '../console-runtime';
import {
  inspectConstructiveSchema,
  type ConstructiveGraphQLRuntime,
  type ConstructiveSchemaSnapshot
} from '../console-kit/constructive/constructive-graphql';
import type { ScopeNames } from './scope-names';

/** A host's endpoints, transports and session: Console Kit's adapter context, or createScopeRuntime's. */
export type ScopeRuntime = ConstructiveGraphQLRuntime & Readonly<{
  session: ConsoleSessionSnapshot;
}>;

export type ScopeSchemas = Readonly<{
  admin?: ConstructiveSchemaSnapshot;
  auth?: ConstructiveSchemaSnapshot;
  /** The app API, where each scope's files and uploads are. */
  data?: ConstructiveSchemaSnapshot;
}>;

/** One scope's members or files: the app's, or one entity's (an organization, a data room). */
export type ScopeTarget = Readonly<{ names: ScopeNames; entityId?: string }>;

/** The entity an entity scope's reads and writes are limited to; none for `app`. */
export function scopeEntityId(target: ScopeTarget): string | undefined {
  if (!target.names.entity) return undefined;
  if (!target.entityId) {
    throw new Error(`The ${target.names.noun.long} scope needs the id of one ${target.names.noun.long}.`);
  }
  return target.entityId;
}

/**
 * What an app without Console Kit hands the scope blocks: its GraphQL
 * endpoints, who is signed in, and how to read the session token. The token
 * is read right before each request and never kept.
 */
export type ScopeHost = Readonly<{
  /** Endpoint URLs by kind: `admin` and `auth` for members and users, `data` (the app API) for files. */
  endpoints: Readonly<Partial<Record<ConsoleEndpointKind, string>>>;
  /** The signed-in user's id; null when no one is signed in. */
  userId: string | null;
  getAccessToken: () => string | null | undefined;
  fetch?: typeof fetch;
}>;

export function createScopeRuntime(host: ScopeHost): ScopeRuntime {
  const identity: ConsoleIdentity = host.userId
    ? { kind: 'authenticated', cachePartition: host.userId, subjectId: host.userId }
    : { kind: 'anonymous', cachePartition: 'anonymous' };
  const endpoints: Partial<Record<ConsoleEndpointKind, ConsoleEndpoint>> = {};
  for (const [kind, url] of Object.entries(host.endpoints) as Array<[ConsoleEndpointKind, string | undefined]>) {
    if (url) endpoints[kind] = { id: kind, kind, url };
  }
  const transport = createFetchConsoleTransport(host.fetch ?? ((input, init) => fetch(input, init)));
  return {
    endpoints,
    session: identity.kind === 'authenticated'
      ? { status: 'authenticated', identity }
      : { status: 'anonymous', identity },
    transportFor: (kind) => {
      const endpoint = endpoints[kind];
      if (!endpoint) return null;
      return createIdentityScopedTransport(transport, {
        endpoint,
        identity,
        getAccessToken: () => host.getAccessToken()
      });
    }
  };
}

type SchemaKind = 'admin' | 'auth' | 'data';

// One introspection per endpoint and signed-in user for the life of the page:
// panels mount and unmount as the user moves around, and a schema is large.
const schemaCache = new Map<string, Promise<ScopeSchemas[SchemaKind]>>();

function inspectOnce(runtime: ScopeRuntime, kind: SchemaKind): Promise<ScopeSchemas[SchemaKind]> {
  const endpoint = runtime.endpoints[kind];
  if (!endpoint) return Promise.resolve(undefined);
  const subject = runtime.session.status === 'authenticated' ? runtime.session.identity.subjectId : '';
  const key = `${kind}\n${endpoint.url}\n${subject}`;
  const cached = schemaCache.get(key);
  if (cached) return cached;
  const loading = inspectConstructiveSchema(runtime, kind);
  // A failed introspection is tried again on the next load, not kept.
  loading.catch(() => schemaCache.delete(key));
  schemaCache.set(key, loading);
  return loading;
}

/**
 * The schemas a scope block checks its reads and writes against: only the
 * endpoints it names. The admin schema is required when asked for; without
 * the auth schema members show without names or emails, and without the
 * app's (`data`) there are no files.
 */
export async function loadScopeSchemas(
  runtime: ScopeRuntime,
  kinds: readonly SchemaKind[]
): Promise<ScopeSchemas> {
  const loaded = await Promise.all(kinds.map(async (kind) => {
    const schema = kind === 'admin'
      ? await inspectOnce(runtime, kind)
      : await inspectOnce(runtime, kind).catch((): undefined => undefined);
    return [kind, schema] as const;
  }));
  return Object.fromEntries(loaded.filter(([, schema]) => schema)) as ScopeSchemas;
}

import {
  executeConstructiveGraphQL,
  fieldsForType,
  namedTypeName,
  selectExistingFields,
  type ConstructiveSchemaSnapshot
} from '../console-kit/constructive/constructive-graphql';
import { asBoolean, asString, connectionNodes } from '../console-kit/constructive/constructive-values';
import type { ScopeRuntime } from './scope-runtime';
import { scopeNames, type ScopeNames } from './scope-names';

/** One scope of the database's scope tree, from the admin API's `membershipTypes`. */
export type MembershipType = Readonly<{
  scope: ScopeNames;
  /** The membership type's id, when the API shows it. */
  id?: number;
  /**
   * Whether each entity of this scope is also a row in the users table, as an
   * organization is. That row's `type` is this membership type's id.
   */
  hasUsersTableEntry: boolean;
}>;

/**
 * The database's membership scopes: `app`, `org`, and every entity type a
 * blueprint added. It asks only for the fields the admin schema has, when the
 * schema is given, and leaves out a scope name the client can't use.
 */
export async function loadMembershipTypes(
  runtime: ScopeRuntime,
  admin?: ConstructiveSchemaSnapshot,
  signal?: AbortSignal
): Promise<MembershipType[]> {
  let fields = ['scope'];
  if (admin) {
    const root = admin.queryFields.membershipTypes;
    if (!root) return [];
    const connection = namedTypeName(root.type);
    const node = connection ? namedTypeName(fieldsForType(admin, connection).nodes?.type) : null;
    if (node && admin.types[node]) fields = selectExistingFields(admin, node, ['id', 'scope', 'hasUsersTableEntry']);
    if (!fields.includes('scope')) return [];
  }
  const data = await executeConstructiveGraphQL<Record<string, unknown>>(
    runtime,
    'admin',
    `query ConsoleKitMembershipTypes { membershipTypes { nodes { ${fields.join(' ')} } } }`,
    undefined,
    signal
  );
  return connectionNodes(data.membershipTypes).flatMap((node): MembershipType[] => {
    const scope = asString(node.scope);
    if (!scope) return [];
    let names: ScopeNames;
    try {
      names = scopeNames(scope);
    } catch {
      return [];
    }
    return [{
      scope: names,
      ...(typeof node.id === 'number' ? { id: node.id } : {}),
      hasUsersTableEntry: asBoolean(node.hasUsersTableEntry)
    }];
  });
}

/**
 * The users-table `type` values that mark an entity (an organization) rather
 * than a person: the ids of the scopes whose entities have a users row.
 */
export function entityUserTypes(types: readonly MembershipType[]): ReadonlySet<number> {
  return new Set(types.flatMap((type) => (type.hasUsersTableEntry && type.id != null ? [type.id] : [])));
}

import {
  executeConstructiveConnectionQuery,
  executeConstructiveGraphQL,
  fieldsForType,
  namedTypeName,
  selectExistingFields
} from '../console-kit/constructive/constructive-graphql';
import { asString } from '../console-kit/constructive/constructive-values';
import { loadMembershipTypes } from './membership-types';
import type { ScopeRuntime, ScopeSchemas } from './scope-runtime';
import { scopeMutation, type ScopeNames } from './scope-names';

/** An invitation the signed-in user can accept, in any membership scope. */
export type PendingInvite = Readonly<{
  id: string;
  scope: ScopeNames;
  /** The entity it admits to; none for an app invitation. */
  entityId?: string;
  senderId?: string;
  senderName?: string;
  expiresAt?: string;
}>;

/** Every pending invitation to the signed-in user, in each scope that lists them. */
export async function loadPendingInvites(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  signal: AbortSignal
): Promise<PendingInvite[]> {
  if (runtime.session.status !== 'authenticated') return [];
  const admin = schemas.admin;
  const scopes = (await loadMembershipTypes(runtime, admin, signal))
    .map((type) => type.scope)
    .filter((names) => Boolean(admin?.queryFields[`myPending${names.pascal}Invites`]));
  const lists = await Promise.all(scopes.map(async (names) => {
    const fieldName = `myPending${names.pascal}Invites`;
    // Each scope's record has its own fields: an app invitation names no entity.
    const nodeFields = admin ? selectExistingFields(admin, pendingRecordType(admin, fieldName), [
      'id', 'entityId', 'senderId', 'expiresAt'
    ]) : [];
    if (!nodeFields.includes('id')) return [];
    const rows = await executeConstructiveConnectionQuery(runtime, 'admin', {
      operationName: `ConsoleKitMyPending${names.pascal}Invites`,
      fieldName,
      nodeSelection: nodeFields.join(' ')
    }, signal);
    return rows.flatMap((row): PendingInvite[] => {
      const id = asString(row.id);
      if (!id) return [];
      return [{
        id,
        scope: names,
        ...(names.entity && asString(row.entityId) ? { entityId: asString(row.entityId)! } : {}),
        ...(asString(row.senderId) ? { senderId: asString(row.senderId)! } : {}),
        ...(asString(row.expiresAt) ? { expiresAt: asString(row.expiresAt)! } : {})
      }];
    });
  }));
  const invites = lists.flat();
  const senderIds = [...new Set(invites.flatMap((invite) => (invite.senderId ? [invite.senderId] : [])))];
  const names = await senderNames(runtime, schemas, senderIds, signal);
  return invites.map((invite) => {
    const senderName = invite.senderId ? names.get(invite.senderId) : undefined;
    return senderName ? { ...invite, senderName } : invite;
  });
}

// The node type of a `myPending<Scope>Invites` connection, as the schema names it.
function pendingRecordType(schema: NonNullable<ScopeSchemas['admin']>, fieldName: string): string {
  const connection = namedTypeName(schema.queryFields[fieldName]?.type);
  return (connection && namedTypeName(fieldsForType(schema, connection).nodes?.type)) ?? '';
}

// The senders' display names, when the auth API shows them to this user.
async function senderNames(
  runtime: ScopeRuntime,
  schemas: ScopeSchemas,
  ids: readonly string[],
  signal: AbortSignal
): Promise<Map<string, string>> {
  const names = new Map<string, string>();
  if (ids.length === 0 || !schemas.auth?.queryFields.users) return names;
  const rows = await executeConstructiveConnectionQuery(runtime, 'auth', {
    operationName: 'ConsoleKitInviteSenders',
    fieldName: 'users',
    nodeSelection: 'id displayName username',
    in: { id: ids }
  }, signal).catch((): Record<string, unknown>[] => []);
  for (const row of rows) {
    const id = asString(row.id);
    const name = asString(row.displayName) ?? asString(row.username);
    if (id && name) names.set(id, name);
  }
  return names;
}

/** Accepts one pending invitation as the signed-in user. */
export async function acceptPendingInvite(runtime: ScopeRuntime, invite: PendingInvite): Promise<void> {
  const mutation = scopeMutation(invite.scope, 'accept', 'Invite');
  const operation = mutation[0]!.toUpperCase() + mutation.slice(1);
  await executeConstructiveGraphQL(
    runtime,
    'admin',
    `mutation ConsoleKit${operation}($input: ${operation}Input!) { ${mutation}(input: $input) { clientMutationId } }`,
    { input: { inviteId: invite.id } }
  );
}

import {
  executeConstructiveConnectionQuery,
  executeConstructiveGraphQL
} from '../console-kit/constructive/constructive-graphql';
import { asBoolean, asRecord, asString, hasEffectiveCapability } from '../console-kit/constructive/constructive-values';
import type { ScopeRuntime } from './scope-runtime';
import { scopeField, type ScopeNames } from './scope-names';

/**
 * Where the user's records go: their personal workspace (their own user,
 * which is also their personal organization) or an organization they belong
 * to. A record's organization key takes the active workspace's id.
 */
export type Workspace = Readonly<{ id: string; name: string; personal: boolean }>;

export type LoadedWorkspaces = Readonly<{
  workspaces: readonly Workspace[];
  /** The app grants the user `create_entity`, so they can start an organization. */
  canCreate: boolean;
}>;

/**
 * The workspaces of the signed-in user in a users-table scope (`org`): the
 * personal one, then each organization where their membership is active, by
 * the names the auth API shows. It reads only rows, never a schema, since
 * every page of an app with a switcher loads it.
 */
export async function loadWorkspaces(
  runtime: ScopeRuntime,
  names: ScopeNames,
  signal: AbortSignal
): Promise<LoadedWorkspaces> {
  if (runtime.session.status !== 'authenticated') return { workspaces: [], canCreate: false };
  const userId = runtime.session.identity.subjectId;
  const [memberships, users, appMemberships, appCapabilities] = await Promise.all([
    executeConstructiveConnectionQuery(runtime, 'admin', {
      operationName: `ConsoleKit${names.pascal}Workspaces`,
      fieldName: scopeField(names, 'Memberships'),
      nodeSelection: 'entityId isActive',
      equalTo: { actorId: userId }
    }, signal),
    // Names are a nicety: without them, an organization shows by its id.
    executeConstructiveConnectionQuery(runtime, 'auth', {
      operationName: 'ConsoleKitWorkspaceNames',
      fieldName: 'users',
      nodeSelection: 'id displayName username'
    }, signal).catch((): Record<string, unknown>[] => []),
    executeConstructiveConnectionQuery(runtime, 'admin', {
      operationName: 'ConsoleKitWorkspaceAppMembership',
      fieldName: 'appMemberships',
      nodeSelection: 'actorId isActive isAdmin capabilities',
      equalTo: { actorId: userId }
    }, signal).catch((): Record<string, unknown>[] => []),
    executeConstructiveConnectionQuery(runtime, 'admin', {
      operationName: 'ConsoleKitWorkspaceAppCapabilities',
      fieldName: 'appCapabilities',
      nodeSelection: 'name bitstr'
    }, signal).catch((): Record<string, unknown>[] => [])
  ]);
  const userById = new Map(users.flatMap((user) => {
    const id = asString(user.id);
    return id ? [[id, user] as const] : [];
  }));
  const organizations = memberships.flatMap((membership): Workspace[] => {
    const id = asString(membership.entityId);
    if (!id || id === userId || !asBoolean(membership.isActive)) return [];
    const user = userById.get(id);
    return [{
      id,
      name: asString(user?.displayName) ?? asString(user?.username) ?? `Organization ${id.slice(0, 8)}`,
      personal: false
    }];
  });
  const appMembership = appMemberships.find((row) => asString(row.actorId) === userId);
  const active = asBoolean(appMembership?.isActive);
  const canCreate = active && (asBoolean(appMembership?.isAdmin) ||
    hasEffectiveCapability(appMembership, appCapabilities, 'create_entity'));
  return {
    workspaces: orderedWorkspaces([{ id: userId, name: 'Personal', personal: true }, ...organizations]),
    canCreate
  };
}

/** The switcher's order: the personal workspace, then organizations by name. */
export function orderedWorkspaces(workspaces: readonly Workspace[]): Workspace[] {
  return [...workspaces].sort((a, b) => Number(b.personal) - Number(a.personal) || a.name.localeCompare(b.name));
}

const CREATE_ORGANIZATION = /* GraphQL */ `
  mutation ConsoleKitCreateWorkspaceOrganization($input: CreateUserInput!) {
    createUser(input: $input) { user { id } }
  }
`;

// An entity of a users-table scope is a users row whose `type` is the
// scope's membership type id, as the database's scope tree records it.
async function usersRowType(runtime: ScopeRuntime, names: ScopeNames, signal?: AbortSignal): Promise<number> {
  const [row] = await executeConstructiveConnectionQuery(runtime, 'admin', {
    operationName: `ConsoleKit${names.pascal}UsersRowType`,
    fieldName: 'membershipTypes',
    nodeSelection: 'id hasUsersTableEntry',
    equalTo: { scope: names.scope }
  }, signal);
  if (typeof row?.id !== 'number' || !asBoolean(row.hasUsersTableEntry)) {
    throw new Error(`This app can't start ${names.noun.long}s: they aren't users rows.`);
  }
  return row.id;
}

/**
 * Starts an organization owned by the signed-in user: the backend makes the
 * organization a users row of its scope's type and the creator its owner.
 * Fails when the owner membership doesn't follow, so a half-made organization
 * is never selected.
 */
export async function createOrganization(
  runtime: ScopeRuntime,
  names: ScopeNames,
  name: string,
  signal?: AbortSignal
): Promise<Workspace> {
  if (runtime.session.status !== 'authenticated') throw new Error('Sign in to start an organization.');
  const userId = runtime.session.identity.subjectId;
  const type = await usersRowType(runtime, names, signal);
  const created = await executeConstructiveGraphQL<Record<string, unknown>>(
    runtime,
    'auth',
    CREATE_ORGANIZATION,
    {
      input: {
        user: { username: `org-${globalThis.crypto.randomUUID()}`, displayName: name, type }
      }
    },
    signal
  );
  const id = asString(asRecord(asRecord(created.createUser)?.user)?.id);
  if (!id) throw new Error('The organization was not created.');
  const owner = await executeConstructiveConnectionQuery(runtime, 'admin', {
    operationName: `ConsoleKit${names.pascal}NewOwner`,
    fieldName: scopeField(names, 'Memberships'),
    nodeSelection: 'actorId isOwner isActive',
    equalTo: { entityId: id, actorId: userId }
  }, signal);
  if (!owner.some((row) => asBoolean(row.isOwner) && asBoolean(row.isActive))) {
    throw new Error('The organization was created, but you are not its active owner yet.');
  }
  return { id, name, personal: false };
}

/**
 * The active workspace per membership scope, readable outside React: a
 * data layer that fills a record's organization key asks
 * `activeWorkspaceId('org')` at create time. The choice is kept per user in
 * localStorage, so a reload or a second tab keeps it, and another user on
 * the same browser starts from their own.
 */

type Listener = () => void;

const listeners = new Set<Listener>();
const memory = new Map<string, string>();

const storageKey = (userId: string, scope: string) => `constructive-workspace:${userId}:${scope}`;

let currentUser: string | null = null;

function read(key: string): string | null {
  try {
    return globalThis.localStorage?.getItem(key) ?? memory.get(key) ?? null;
  } catch {
    return memory.get(key) ?? null;
  }
}

function write(key: string, value: string): void {
  memory.set(key, value);
  try {
    globalThis.localStorage?.setItem(key, value);
  } catch {
    // Private windows and blocked storage keep the choice for this page only.
  }
}

/** Whose choices the store reads; set when the session changes. */
export function setWorkspaceUser(userId: string | null): void {
  if (userId === currentUser) return;
  currentUser = userId;
  for (const listener of listeners) listener();
}

/** The active workspace's entity id in `scope`; null before a choice or signed out. */
export function activeWorkspaceId(scope = 'org'): string | null {
  return currentUser ? read(storageKey(currentUser, scope)) : null;
}

export function setActiveWorkspace(scope: string, id: string): void {
  if (!currentUser) return;
  write(storageKey(currentUser, scope), id);
  for (const listener of listeners) listener();
}

export function subscribeWorkspace(listener: Listener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}
